CREATE TRIGGER trg_dp_fine_pay_guard BEFORE INSERT ON bookkeeping_fine_payments WHEN NEW.status='aktif' BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM bookkeeping_fines WHERE id=NEW.fine_id AND status NOT IN ('dibatalkan','lunas') AND amount_rp>=paid_rp+NEW.amount_rp) THEN RAISE(ABORT,'fine-exceeds-outstanding') END;
END

CREATE TRIGGER trg_dp_fine_pay_total AFTER INSERT ON bookkeeping_fine_payments WHEN NEW.status='aktif' BEGIN
 UPDATE bookkeeping_fines SET paid_rp=paid_rp+NEW.amount_rp,paid_on=NEW.paid_on,status=CASE WHEN paid_rp+NEW.amount_rp>=amount_rp THEN 'lunas' ELSE 'belum' END WHERE id=NEW.fine_id;
END

CREATE TRIGGER trg_dp_loan_pay_guard BEFORE INSERT ON bookkeeping_loan_repayments WHEN NEW.status='aktif' BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM bookkeeping_loans WHERE id=NEW.loan_id AND status='aktif') THEN RAISE(ABORT,'loan-not-active') END;
 SELECT CASE WHEN NEW.amount_rp > (SELECT l.amount_rp-COALESCE((SELECT SUM(r.amount_rp) FROM bookkeeping_loan_repayments r WHERE r.loan_id=l.id AND r.status='aktif'),0) FROM bookkeeping_loans l WHERE l.id=NEW.loan_id) THEN RAISE(ABORT,'loan-overpayment') END;
END

CREATE TRIGGER trg_dp_loan_pay_status AFTER INSERT ON bookkeeping_loan_repayments WHEN NEW.status='aktif' BEGIN
 UPDATE bookkeeping_loans SET status='lunas' WHERE id=NEW.loan_id AND amount_rp=(SELECT COALESCE(SUM(amount_rp),0) FROM bookkeeping_loan_repayments WHERE loan_id=NEW.loan_id AND status='aktif');
END
